                "Object", LabelPrinter.class.getSuperclass().getSimpleName());

        LabelPrinter printer = new LabelPrinter(20);
        check("print(\"hello\") succeeds", true, printer.print("hello"));
        check("printing burned 5 units", 15, printer.inkLevel());
        check("a label that needs too much ink fails", false, printer.print("sixteen characters"));
        check("failed print burned no ink", 15, printer.inkLevel());
        check("null label is refused", false, printer.print(null));
        check("only successful prints are counted", 1, printer.printedCount());

        printer.refill();
        check("refill tops the cartridge up", 100, printer.inkLevel());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
