/**
 * TASK: Complete LabelPrinter. The InkCartridge class above it is provided
 * and already works -- do not change it.
 *
 * A LabelPrinter HAS an InkCartridge; it must NOT extend InkCartridge.
 * The test checks that LabelPrinter's superclass is still Object, so the
 * only way through is delegation: keep a private cartridge field and call
 * its methods.
 *
 * Rules:
 *   - the constructor creates the cartridge with the given ink units
 *   - print(label) costs one ink unit per character; a null or empty label
 *     prints nothing and returns false; if the cartridge cannot supply that
 *     many units nothing is drawn and it returns false
 *   - a successful print returns true and counts toward printedCount()
 *   - inkLevel() reports the cartridge level, refill() tops it back up
 *
 * Example: new LabelPrinter(20), print("hello") -> true, inkLevel() 15.
 */
class InkCartridge {

    private int units;

    InkCartridge(int units) {
        this.units = units;
    }

    int level() {
        return units;
    }

    boolean draw(int amount) {
        if (amount <= 0 || amount > units) {
            return false;
        }
        units = units - amount;
        return true;
    }

    void refill() {
        units = 100;
    }
}

public class LabelPrinter {

    private final InkCartridge cartridge;
    private int printed = 0;

    public LabelPrinter(int ink) {
        this.cartridge = new InkCartridge(ink);
    }

    public boolean print(String label) {
        if (label == null || label.isEmpty()) {
            return false;
        }
        if (!cartridge.draw(label.length())) {
            return false;
        }
        printed++;
        return true;
    }

    public int inkLevel() {
        return cartridge.level();
    }

    public void refill() {
        cartridge.refill();
    }

    public int printedCount() {
        return printed;
    }
}
